insert into customers(code,name,email) values('C01','Harbour Water Lab Client','water@example.invalid'),('C02','Southern Materials','materials@example.invalid') on conflict do nothing;
insert into methods(code,name,revision,unit,lower_limit,upper_limit,validation_ref) values('PH','Water pH','demo-1','pH',6.5,8.5,'DEMO-VALIDATION-PH'),('TURB','Turbidity','demo-1','NTU',0,1,'DEMO-VALIDATION-TURB'),('SOLIDS','Total solids','demo-1','mg/L',0,500,null) on conflict do nothing;
insert into equipment(code,name,calibrated_on,calibration_due,certificate_ref) values('PH01','Bench pH meter',current_date-100,current_date+90,'DEMO-CAL-PH'),('TB01','Turbidity meter',current_date-400,current_date-10,'DEMO-CAL-TB'),('BL01','Analytical balance',current_date-30,current_date+330,'DEMO-CAL-BL') on conflict do nothing;
insert into samples(code,name,customer_id,matrix,collected_at,received_at,due_date,condition,location) values
('S001','River inlet',(select id from customers where code='C01'),'Water',now()-interval '8 days',now()-interval '7 days',current_date-2,'Intact','Cold room'),
('S002','River outlet',(select id from customers where code='C01'),'Water',now()-interval '4 days',now()-interval '3 days',current_date-1,'Intact','Cold room'),
('S003','Process rinse',(select id from customers where code='C02'),'Water',now()-interval '2 days',now()-interval '1 day',current_date+2,'Seal damaged','Intake hold'),
('S004','Aggregate wash',(select id from customers where code='C02'),'Water',null,now()-interval '1 day',current_date+3,'Intact','Intake') on conflict do nothing;
insert into tests(code,sample_id,method_id,equipment_id,analyst,due_date) select x.code,s.id,m.id,e.id,x.analyst,current_date+x.offset_days from (values('T001','S001','PH','PH01','Aroha',-2),('T002','S001','TURB','TB01','Aroha',-2),('T003','S002','PH','PH01','Ben',-1),('T004','S003','SOLIDS','BL01','Ben',2)) x(code,sample,method,equipment,analyst,offset_days) join samples s on s.code=x.sample join methods m on m.code=x.method join equipment e on e.code=x.equipment on conflict do nothing;
insert into results(test_id,revision,value,uncertainty,measured_at,analyst,raw_ref,qc,reason,method_snapshot,equipment_snapshot) select t.id,1,x.value,0.1,now()-interval '2 days',t.analyst,'DEMO-RAW-'||t.code,x.qc,'Initial demo result',to_jsonb(m),to_jsonb(e) from (values('T001',7.2,'pass'),('T002',1.8,'fail'),('T003',7.5,'pass')) x(code,value,qc) join tests t on t.code=x.code join methods m on m.id=t.method_id join equipment e on e.id=t.equipment_id on conflict do nothing;
insert into reviews(result_id,reviewer,note) select r.id,'Casey','Demo technical review only' from results r join tests t on t.id=r.test_id where t.code='T001' on conflict do nothing;
insert into custody(sample_id,happened_at,handler,location,note) select s.id,s.received_at,'Intake operator',s.location,'Demo receipt' from samples s where s.code in ('S001','S002','S003') and not exists(select 1 from custody c where c.sample_id=s.id);
insert into issues(code,sample_id,description,owner,due_date) values('I001',(select id from samples where code='S003'),'Damaged seal: request sampling context','Casey',current_date-1) on conflict do nothing;
